class Solution:
    def smallestRange(self, nums: list[list[int]]) -> list[int]:
        from collections import defaultdict
        merged = []
        for r, arr in enumerate(nums):
            for x in arr:
                merged.append((x, r))
        merged.sort()
        need = len(nums)
        counts = defaultdict(int)
        have = 0
        left = 0
        best = [-10**18, 10**18]
        for right, (x, r) in enumerate(merged):
            if counts[r] == 0:
                have += 1
            counts[r] += 1
            while have == need:
                lo = merged[left][0]
                if x - lo < best[1] - best[0] or (x - lo == best[1] - best[0] and lo < best[0]):
                    best = [lo, x]
                lr = merged[left][1]
                counts[lr] -= 1
                if counts[lr] == 0:
                    have -= 1
                left += 1
        return best

